// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

let points = [];
let nClusters = 12;
let margin = 80;

function setup() {
	createCanvas(500, 500);
	noLoop();
	noStroke();

	for (let i = 0; i < 5000; i++) {
		let x = random(margin, width-margin);
		let y = random(margin, height-margin);
		if (dist(x, y, width/2, height/2) < (width-2*margin)/2) points.push(createVector(x, y));
	}
}

function draw() {
	background(5);
	let clusters = divide(points);
	for (let i = 0; i < nClusters; i++) {
		let colors = ["#fffbe6", 5];
		let cluster = clusters[i];
		let hull = convexHull(cluster);
		let j = 0;
		while (hull.length > 5) {
			if (j % 3 == 0) {
				fill(colors[0]);
				drawHull(hull);
				colors = [colors[1], colors[0]];
			}
			j++;

			let subcluster = [];
			for (let p of cluster) {
				if (hull.indexOf(p) == -1) {
					subcluster.push(p);
				}
			}
			if (subcluster.length == 0) break;
			hull = convexHull(subcluster);
			cluster = subcluster;
		}
	}
}

// divide points into convex clusters
function divide(points) {
	let clusters = [];

	// initialize centroids randomly
	let centroids = [];
	for (let i = 0; i < nClusters; i++) {
		let c;
		do {
			c = random(points);
		} while (centroids.indexOf(c) != -1)
		c.id = i;
		centroids.push(c);
		clusters.push([]);
	}

	for (let i = 0; i < 2; i++) voronoiRelaxation(centroids)

	// assign clusters
	for (let p of points) {
		let argmin = 0;
		let minDist = distSquared(p, centroids[0]);
		for (let i = 1; i < nClusters; i++) {
			let d = distSquared(p, centroids[i]);
			if (d < minDist) {
				minDist = d;
				argmin = i;
			}
		}
		clusters[argmin].push(p);
	}

	return clusters;
}

function voronoiRelaxation(centroids) {
	let n = 20, s = width/n;
	let voronoi = Array(nClusters).fill().map(()=>[]);
	for (let i = 0; i < n; i++) {
		let x = (i+1/2)*s;
		for (let j = 0; j < n; j++) {
			let y = (j+1/2)*s;
			let cid = closestCentroidId(centroids, {x: x, y: y});
			voronoi[cid].push({x: x, y: y});
		}
	}

	for (let i = 0; i < nClusters; i++) {
		let c = centroids[i];
		let cellPoints = voronoi[c.id];
		let xSum = 0, ySum = 0;
		for (let p of cellPoints) {
			xSum += p.x;
			ySum += p.y;
		}
		let x1 = constrain(xSum/cellPoints.length, margin, width-margin);
		let y1 = constrain(ySum/cellPoints.length, margin, height-margin);
		if (dist(x1, y1, width/2, height/2) > (width-2*margin)/2) {
			let theta = atan2(y1-height/2, x1-width/2);
			let r = (width-2*margin)/2;
			x1 = width/2 + r*cos(theta);
			y1 = height/2 + r*sin(theta);
		}
		c.x = x1;
		c.y = y1;
	}
}

function closestCentroidId(centroids, p) {
	let minDist = Infinity, idMin = -1;
	for (let c of centroids) {
		let d = distSquared(c, p);
		if (d < minDist) {
			minDist = d;
			idMin = c.id;
		}
	}
	return idMin;
}

function convexHull(points) {
	// adapted from https://en.wikipedia.org/wiki/Gift_wrapping_algorithm#Pseudocode
	points.sort((p, q) => p.x - q.x);
	let hull = [];
	let i = 0;
	let endPoint;
	let pointOnHull = points[0];
	do {
		hull.push(pointOnHull);
		endPoint = points[0];
		for (let j = 0; j < points.length; j++) {
			let p = p5.Vector.sub(endPoint, pointOnHull);
			let q = p5.Vector.sub(points[j], pointOnHull);
			if (endPoint.equals(pointOnHull) || (p.cross(q)).z < 0) {
				endPoint = points[j];
			}
    }
    i++;
    pointOnHull = endPoint;
	} while (!endPoint.equals(points[0]));
	return hull;
}

function distSquared(p, q) {
	return sq(p.x - q.x) + sq(p.y - q.y);
}

function drawHull(hull) {
	beginShape();
	for (let p of hull) {
		vertex(p.x, p.y);
	}
	endShape(CLOSE);
}

